INSERT INTO swiss_quiz_kb (regione_id, tipo, domanda, opzioni, corretta, risposta_modello, elementi, spiegazione) VALUES
('VALLESE','multipla','Qual è il cantone svizzero con la maggiore superficie vitata?','{"a":"Vaud","b":"Vallese","c":"Ginevra","d":"Ticino"}','"b"',NULL,NULL,'Il Vallese ha 4.800 ha, circa 1/3 della produzione vinicola svizzera. Primo cantone per superficie.'),
('VALLESE','multipla','Come si chiamano le terrazze tipiche della viticoltura eroica del Vallese?','{"a":"Bancali","b":"Tablar","c":"Fasce","d":"Muretti"}','"b"',NULL,NULL,'Le terrazze del Vallese si chiamano Tablar, sostenute da muretti a secco. Meccanizzazione quasi impossibile.'),
('VALLESE','multipla','A quale altitudine si trovano i vigneti di Visperterminen, tra i più alti d''Europa?','{"a":"800 m","b":"950 m","c":"1.100 m","d":"1.300 m"}','"c"',NULL,NULL,'Visperterminen raggiunge 1.100 m s.l.m., tra i vigneti più alti d''Europa. Ha propria AOC Grand Cru.'),
('VALLESE','multipla','La denominazione Fendant è riservata esclusivamente a quale vitigno?','{"a":"Sylvaner","b":"Pinot Gris","c":"Chasselas","d":"Petite Arvine"}','"c"',NULL,NULL,'Fendant è la denominazione AOC esclusiva del Vallese per Chasselas 100%.'),
('VALLESE','multipla','La denominazione Johannisberg del Vallese è prodotta al 100% da quale vitigno?','{"a":"Riesling","b":"Sylvaner","c":"Gewürztraminer","d":"Marsanne"}','"b"',NULL,NULL,'Il Johannisberg del Vallese è Sylvaner 100%. Non ha nulla a che fare con il Riesling tedesco.'),
('VALLESE','multipla','Quante sono le AOC Grand Cru del Vallese?','{"a":"6","b":"8","c":"10","d":"12"}','"c"',NULL,NULL,'Il Vallese ha 10 AOC Grand Cru: Visperterminen, Saillon, Leytron, Chamoson, Vétroz, Conthey, Sion, Saint-Léonard, Sierre, Salquenen.'),
('VALLESE','multipla','Il vento Föhn nel Vallese ha quale effetto principale sulla viticoltura?','{"a":"Aumenta le precipitazioni","b":"Accelera la maturazione delle uve","c":"Riduce le gelate primaverili","d":"Porta umidità dal Mediterraneo"}','"b"',NULL,NULL,'Il Föhn è un vento caldo e secco che scende dalle Alpi. Nel Vallese accelera la maturazione, compensando le alte altitudini.'),
('VALLESE','multipla','Il Grain Noble ConfidenCiel richiede un minimo di quanti gradi Oechslé?','{"a":"90","b":"110","c":"130","d":"150"}','"c"',NULL,NULL,'Minimo 130 gradi Oechslé senza aggiunta di zucchero. Le uve devono provenire da viti di almeno 15 anni.'),
('VALLESE','multipla','In quale comune del Vallese si coltiva principalmente l''Amigne su morena glaciale e scisto nero?','{"a":"Sierre","b":"Martigny","c":"Vétroz","d":"Fully"}','"c"',NULL,NULL,'Vétroz è il comune per eccellenza dell''Amigne, con suoli di morena glaciale e scisto nero.'),
('VALLESE','multipla','Quale vitigno è coltivato principalmente a Salquenen, unico comune a maggioranza tedesca nel Vallese?','{"a":"Chasselas","b":"Pinot Noir","c":"Cornalin","d":"Syrah"}','"b"',NULL,NULL,'Salquenen (Salgesch) è famosa per il Pinot Noir e ha propria AOC Grand Cru. Unico comune germanofono nella zona viticola romanda.'),
('VALLESE','vero_falso','Il Vallese è la regione più secca della Svizzera con circa 650 mm di precipitazioni annue e 2.500 ore di sole.',NULL,'true',NULL,NULL,'Vero. Le Alpi proteggono il Vallese creando ombra pluviometrica. Massima insolazione della Svizzera.'),
('VALLESE','vero_falso','La Dole Blanche è un rosato tipico del Vallese prodotto da Pinot Noir.',NULL,'false',NULL,NULL,'Falso. La Dole Blanche è un vino BIANCO (blanc de noirs) da Pinot Noir e Gamay vinificati in bianco, senza macerazione.'),
('VALLESE','vero_falso','Il Cornalin e l''Humagne Rouge sono i due principali vitigni autoctoni rossi del Vallese.',NULL,'true',NULL,NULL,'Vero. Cornalin e Humagne Rouge sono i due autoctoni rossi. Nota: Humagne Rouge non è imparentato geneticamente con Humagne Blanche.'),
('VALLESE','vero_falso','Il Vin des Glaciers è prodotto esclusivamente da uve Rèze.',NULL,'false',NULL,NULL,'Falso. È un assemblaggio di autoctoni: Rèze, Ermitage, Malvoisie, talvolta Päien. Non è monovitigno.'),
('VALLESE','vero_falso','Il Grain Noble ConfidenCiel prevede un invecchiamento minimo di 12 mesi in legno.',NULL,'true',NULL,NULL,'Vero. Il disciplinare impone almeno 12 mesi in legno oltre ai requisiti su vitigni, Oechslé e degustazione interna.'),
('VALLESE','vero_falso','Chamoson è il secondo comune viticolo più grande della Svizzera dopo Satigny.',NULL,'true',NULL,NULL,'Vero. Con circa 400 ha, Chamoson è il secondo comune viticolo svizzero per estensione, dopo Satigny (Ginevra).'),
('VALLESE','aperta','Descrivi le caratteristiche climatiche del Vallese e perché è la regione più secca della Svizzera.',NULL,NULL,'Clima continentale protetto dalle Alpi. Ombra pluviometrica: 650 mm/anno (meno piovosa CH). Insolazione 2.500 ore/anno (massima CH). Vento Föhn accelera la maturazione. Rischio gelate invernali. Calura estiva intensa. Spesso necessaria irrigazione artificiale.',NULL,'Clima continentale protetto dalle Alpi, 650 mm pioggia (minima CH), 2.500 ore sole (massima CH), Föhn che accelera maturazione, rischio gelate, irrigazione spesso necessaria.'),
('VALLESE','aperta','Descrivi il Grain Noble ConfidenCiel: origini, requisiti, vitigni ammessi.',NULL,NULL,'Creato nel 1996 da ~30 produttori. Requisiti: vitigni tradizionali vallesi (Petite Arvine, Ermitage, Johannisberg, Amigne, Paien, Malvoisie), viti almeno 15 anni, minimo 130 gradi Oechslé senza aggiunta zucchero, invecchiamento minimo 12 mesi in legno, degustazione interna dalla commissione del gruppo.',NULL,'Creato 1996 da ~30 produttori. Vitigni: Petite Arvine, Ermitage, Johannisberg, Amigne, Paien, Malvoisie. Min 130° Oechslé, viti 15+anni, 12 mesi legno, degustazione interna.'),
('VALLESE','aperta','Cos''è il Vin des Glaciers e dove viene prodotto? Descrivi la tecnica produttiva.',NULL,NULL,'Vino bianco ossidativo della Val d''Anniviers nel Vallese. Assemblaggio autoctoni: Rèze, Ermitage/Marsanne, Malvoisie/Pinot Gris, Päien/Savagnin Blanc. Sistema equivalente alla Solera spagnola in botti di larice: il vino evaporato viene reintegrato con vino più giovane, creando un vino ossidativo di carattere unico.',NULL,'Vino bianco ossidativo, Val d''Anniviers. Assemblaggio autoctoni (Rèze, Ermitage, Malvoisie, Päien). Sistema Solera in botti di larice: evaporato reintegrato con vino più giovane.'),
('VALLESE','aperta','Spiega le differenze tra le tre sottozone viticole del Vallese in termini di vitigni e suoli.',NULL,NULL,'Basso Vallese (Fully, Martigny): suoli granitici alluvionali, Gamay e Petite Arvine, influenza atlantica. Vallese Centrale (Chamoson, Sion, Sierre): coni di deiezione e scisti, zona più calda, maggior parte dei Grand Cru, Pinot Noir, Amigne di Vétroz, Sylvaner di Chamoson. Alto Vallese (Visperterminen): suoli granitici d''alta quota fino a 1.100 m, Päien/Heida e Rèze, stile fresco e austero.',NULL,'Basso Vallese: granito alluvionale, Gamay e Petite Arvine. Centrale: coni di deiezione, Grand Cru, Amigne Vétroz, Sylvaner Chamoson. Alto Vallese: granito alta quota 1.100 m, Päien/Heida e Rèze.'),
('VALLESE','elenco','Elenca tutti i vitigni bianchi autoctoni del Vallese (minimo 6).',NULL,NULL,'Petite Arvine, Amigne, Humagne Blanche, Rèze, Lafnetscha, Himbertscha, Savagnin Blanc (Päien/Heida), Pinot Gris (Malvoisie), Marsanne (Ermitage), Muscat. Il Vallese ha il più grande bacino di vitigni endemici conservati in Svizzera.',NULL,'Petite Arvine, Amigne, Humagne Blanche, Rèze, Lafnetscha, Himbertscha, Savagnin Blanc (Päien/Heida), Malvoisie, Ermitage, Muscat.'),
('VALLESE','elenco','Elenca le 10 AOC Grand Cru del Vallese.',NULL,NULL,'Visperterminen, Saillon, Leytron, Chamoson, Vétroz, Conthey, Ville de Sion, Saint-Léonard, Sierre, Salquenen.',NULL,'Visperterminen, Saillon, Leytron, Chamoson, Vétroz, Conthey, Sion, Saint-Léonard, Sierre, Salquenen.'),
('VALLESE','elenco','Elenca le 4 denominazioni protette del Vallese e spiega cosa sono.',NULL,NULL,'1. Fendant: AOC Vallese da Chasselas 100%. 2. Johannisberg: AOC Vallese da Sylvaner 100%. 3. Dole: AOC Vallese da Pinot Noir + Gamay (rosso), min 51% PN con dominanza. 4. Dole Blanche: come Dole ma vinificata in bianco (blanc de noirs).',NULL,'Fendant (Chasselas 100%), Johannisberg (Sylvaner 100%), Dole (PN+Gamay rosso, min 51% PN), Dole Blanche (stesso blend vinificato in bianco).'),
('VALLESE','classifica_colore','Classifica questi vitigni autoctoni del Vallese (bianco o rosso):',NULL,'{"Petite Arvine":"Bianco","Cornalin":"Rosso","Humagne Rouge":"Rosso","Amigne":"Bianco","Rèze":"Bianco","Humagne Blanche":"Bianco","Lafnetscha":"Bianco","Savagnin Blanc (Päien)":"Bianco"}',NULL,'["Petite Arvine","Cornalin","Humagne Rouge","Amigne","Rèze","Humagne Blanche","Lafnetscha","Savagnin Blanc (Päien)"]','Solo 2 autoctoni rossi (Cornalin, Humagne Rouge). Molti bianchi. Humagne Blanche e Rouge non sono imparentati geneticamente.'),
('VALLESE','classifica_colore','Classifica questi vitigni coltivati nel Vallese (bianco o rosso):',NULL,'{"Chasselas":"Bianco","Pinot Noir":"Rosso","Gamay":"Rosso","Sylvaner":"Bianco","Marsanne":"Bianco","Syrah":"Rosso","Muscat":"Bianco","Merlot":"Rosso"}',NULL,'["Chasselas","Pinot Noir","Gamay","Sylvaner","Marsanne","Syrah","Muscat","Merlot"]','Il Vallese coltiva sia vitigni internazionali che autoctoni. Pinot Noir 28%, Chasselas 16%, Gamay importanti.'),
('VALLESE','abbinamento','Abbina ogni denominazione protetta del Vallese al suo vitigno o blend:',NULL,'{"Fendant":"Chasselas 100%","Johannisberg":"Sylvaner 100%","Dole":"Pinot Noir + Gamay rosso","Dole Blanche":"Pinot Noir + Gamay vinificato in bianco","Vin des Glaciers":"Assemblaggio autoctoni in botti di larice"}',NULL,'{"sx":["Fendant","Johannisberg","Dole","Dole Blanche","Vin des Glaciers"],"dx":["Chasselas 100%","Sylvaner 100%","Pinot Noir + Gamay rosso","Pinot Noir + Gamay vinificato in bianco","Assemblaggio autoctoni in botti di larice"]}','Le 5 menzioni storiche del Vallese sono legate a specifici vitigni o blend, disciplinati dall''AOC cantonale.'),
('VALLESE','abbinamento','Abbina ogni sottozona del Vallese ai suoi vitigni autoctoni principali:',NULL,'{"Basso Vallese (Fully, Martigny)":"Gamay su granito, Petite Arvine","Vallese Centrale (Chamoson, Vétroz, Sierre)":"Amigne di Vétroz, Sylvaner di Chamoson, Pinot Noir di Salquenen","Alto Vallese (Visperterminen)":"Päien/Heida e Rèze a 1.100 m"}',NULL,'{"sx":["Basso Vallese (Fully, Martigny)","Vallese Centrale (Chamoson, Vétroz, Sierre)","Alto Vallese (Visperterminen)"],"dx":["Gamay su granito, Petite Arvine","Amigne di Vétroz, Sylvaner di Chamoson, Pinot Noir di Salquenen","Päien/Heida e Rèze a 1.100 m"]}','Tre sottozone del Vallese con caratteristiche pedoclimatiche molto distinte.'),
('VALLESE','comuni','In quale sottozona del Vallese si trovano vigneti di Gamay su terreno granitico?','{"a":"Sierre","b":"Fully e Martigny (Basso Vallese)","c":"Vétroz","d":"Visperterminen"}','"b"',NULL,NULL,'Il Gamay su terreno granitico si coltiva a Fully e Martigny nel Basso Vallese. Il granito dà al Gamay carattere minerale e strutturato.'),
('VALLESE','comuni','Quale comune è noto per il Sylvaner su suolo alluvionale (cono di deiezione)?','{"a":"Sierre","b":"Sion","c":"Chamoson","d":"Leytron"}','"c"',NULL,NULL,'Chamoson è il comune per eccellenza del Sylvaner (Johannisberg) nel Vallese, con suoli alluvionali (cono di deiezione) che danno vini grassi e strutturati.'),
('VALLESE','comuni','Nella tradizione viticola del Vallese, cosa sono i Tablar?','{"a":"Le botti di larice per il Vin des Glaciers","b":"Le terrazze viticole su pendii ripidi sostenute da muretti a secco","c":"I vigneti a 1.100 m di Visperterminen","d":"Le cooperative vinicole vallesane"}','"b"',NULL,NULL,'I Tablar sono le terrazze viticole del Vallese, costruite su pendii ripidissimi e sostenute da muretti a secco. Lavoro interamente manuale.'),
('VAUD','multipla','Il Vaud è il secondo cantone svizzero per superficie vitata. Quanti ettari conta?','{"a":"2.800 Ha","b":"3.700 Ha","c":"4.200 Ha","d":"1.900 Ha"}','"b"',NULL,NULL,'Il Vaud ha 3.700 Ha, secondo dopo il Vallese (4.800 Ha). Produce 65% bianchi e 35% rossi.'),
('VAUD','multipla','Il Lavaux è Patrimonio UNESCO da quale anno?','{"a":"2000","b":"2003","c":"2007","d":"2010"}','"c"',NULL,NULL,'Il Lavaux è iscritto all''UNESCO dal 2007, per il paesaggio culturale vitivinicolo eccezionale con i vigneti terrazzati sul Lago Lemano.'),
('VAUD','multipla','Quali sono i due Grand Cru AOC del Lavaux?','{"a":"Dorin e Salvagnin","b":"Dézaley e Calamin","c":"Lavaux e La Côte","d":"Chasselas e Doral"}','"b"',NULL,NULL,'Dézaley e Calamin sono i due Grand Cru AOC del Lavaux (più Dézaley-Marsens Grand Cru come parcella storica).'),
('VAUD','multipla','Su quale tipo di roccia si trova il Grand Cru Dézaley?','{"a":"Granito","b":"Scisto","c":"Poudingue (conglomerato) su marne","d":"Calcare kimmeridgiano"}','"c"',NULL,NULL,'Il Grand Cru Dézaley è su roccia poudingue (conglomerato) su marne. Produce Chasselas opulenti e minerali, longevi 20-30 anni.'),
('VAUD','multipla','Quante AOC regionali ha il cantone Vaud?','{"a":"4","b":"5","c":"6","d":"8"}','"c"',NULL,NULL,'Il Vaud ha 6 AOC regionali: Lavaux, La Côte, Chablais, Côtes-de-l''Orbe, Bonvillars e Vully (condivisa con Friburgo).'),
('VAUD','multipla','Il vento bise nel Vaud ha quale effetto principale?','{"a":"Accelera la maturazione come il Föhn","b":"Riduce i rischi di gelate primaverili e grandine","c":"Porta umidità dal lago Lemano","d":"Aumenta le precipitazioni in primavera"}','"b"',NULL,NULL,'La bise è un vento freddo e secco da nord-est. Nella zona de La Côte riduce gelate primaverili e grandine.'),
('VAUD','multipla','Cosa è il Dorin nel Vaud?','{"a":"Un vitigno autoctono bianco","b":"Una menzione storica legata allo Chasselas","c":"Il nome del vento tipico del Chablais","d":"Una cooperativa vinicola storica"}','"b"',NULL,NULL,'Il Dorin è una menzione storica (non un vitigno diverso) legata allo Chasselas del Vaud.'),
('VAUD','multipla','Cosa è il Salvagnin nel Vaud?','{"a":"Un clone autoctono di Chasselas","b":"Un rosso tradizionale da blend di Pinot Noir e Gamay","c":"Il nome locale del Gamay","d":"Un Grand Cru della zona di La Côte"}','"b"',NULL,NULL,'Il Salvagnin è un vino rosso tradizionale del Vaud da blend di Pinot Noir e Gamay. Il Salvagnin rosé è la versione rosata.'),
('VAUD','multipla','Quale vento soffia nella zona dello Chablais nel Vaud?','{"a":"Bise","b":"Joran","c":"Föhn","d":"Tramontana"}','"c"',NULL,NULL,'Il Föhn soffia nella zona dello Chablais (confine con il Vallese), portando calore e accelerando la maturazione delle uve.'),
('VAUD','multipla','Il Servagnin de Morges è una denominazione storica per quale vitigno?','{"a":"Chasselas autoctono di Morges","b":"Pinot Noir, antico clone locale protetto a Morges","c":"Doral vinificato in rosso","d":"Gamay con invecchiamento prolungato"}','"b"',NULL,NULL,'Il Servagnin de Morges è riservato al Servagnin, antico clone locale di Pinot Noir protetto a Morges, con regole su resa e invecchiamento.'),
('VAUD','vero_falso','Il Chasselas copre circa il 60% della superficie vitata del Vaud.',NULL,'true',NULL,NULL,'Vero. Il Chasselas è il vitigno dominante del Vaud con il 60% della superficie. Simbolo del cantone.'),
('VAUD','vero_falso','Il Doral è un vitigno autoctono rosso del Vaud.',NULL,'false',NULL,NULL,'Falso. Il Doral è un vitigno bianco autoctono (incrocio Chasselas x Chardonnay). I rossi autoctoni sono Plant Robert e Servagnin.'),
('VAUD','vero_falso','Il Lauriers d''Or Terravin è il marchio di qualità della Federazione dei Viticoltori del Vaud assegnato solo ai vini selezionati tramite degustazione da esperti.',NULL,'true',NULL,NULL,'Vero. Il Lauriers d''Or Terravin è assegnato solo ai migliori vini del Vaud selezionati da esperti degustatori.'),
('VAUD','vero_falso','Il Grand Cru Dézaley può essere prodotto sia da Chasselas che da Pinot Noir.',NULL,'false',NULL,NULL,'Falso. Il Grand Cru Dézaley è prodotto esclusivamente da Chasselas. Il Vaud è a vocazione principalmente bianca.'),
('VAUD','vero_falso','L''AOC Vully è condivisa tra il cantone Vaud e il cantone Friburgo.',NULL,'true',NULL,NULL,'Vero. L''AOC Vully si estende su due cantoni: Vaud e Friburgo, nella regione dei Tre Laghi.'),
('VAUD','vero_falso','I vitigni autoctoni bianchi del Vaud sono Doral e Charmont.',NULL,'true',NULL,NULL,'Vero. Doral (Chasselas x Chardonnay) e Charmont sono i due bianchi autoctoni del Vaud. I rossi autoctoni sono Plant Robert e Servagnin.'),
('VAUD','aperta','Descrivi il fenomeno dei tre soli nel Lavaux e il suo impatto sulla qualità del Chasselas.',NULL,NULL,'Il Lavaux beneficia di tre fonti di calore: 1) Sole diretto sui vigneti; 2) Riflesso del sole sul Lago Lemano che amplifica l''irraggiamento sulle viti; 3) Calore accumulato dai muretti a secco delle terrazze e rilasciato di notte alle radici. Questa combinazione permette al Chasselas di raggiungere piena maturazione e sviluppare la complessità minerale dei Grand Cru Dézaley e Calamin.',NULL,'Tre fonti di calore: sole diretto, riflesso sul lago Lemano, calore rilasciato dai muri a secco di notte. Microclima eccezionale per Grand Cru Dézaley e Calamin.'),
('VAUD','aperta','Descrivi le menzioni e denominazioni tradizionali del Vaud (almeno 4) e spiega cosa indicano.',NULL,NULL,'1. Dorin: menzione storica per il Chasselas del Vaud. 2. Salvagnin: rosso da blend Pinot Noir e Gamay. 3. Servagnin de Morges: Pinot Noir antico clone di Morges con regole stringenti. 4. Lauriers d''Or Terravin: etichetta di qualità della Federazione Viticoltori per i migliori vini. 5. Premier Grand Cru: legato a Clos, Château o parcelle storiche.',NULL,'Dorin (Chasselas menzione storica), Salvagnin (PN+Gamay rosso), Servagnin de Morges (clone storico PN), Lauriers d''Or Terravin (etichetta qualità), Premier Grand Cru (parcelle storiche).'),
('VAUD','aperta','Descrivi le differenze principali tra Lavaux e La Côte nel Vaud.',NULL,NULL,'Lavaux: vigneti terrazzati sul Lago Lemano, Patrimonio UNESCO, tre soli, roccia poudingue nei Grand Cru Dézaley e Calamin, vini più strutturati e longevi. Vento bise. La Côte: la sottozona più grande del Vaud per superficie, suoli argillosi e alluvionali, Chasselas più leggeri e fruttosi, Servagnin de Morges per il Pinot Noir, denominazione Salvagnin.',NULL,'Lavaux: terrazzato, UNESCO, tre soli, poudingue, Grand Cru longevi. La Côte: più grande, suoli alluvionali, Chasselas più leggero, Servagnin de Morges, Salvagnin.'),
('VAUD','aperta','Quali sono i vitigni autoctoni del Vaud e dove vengono coltivati?',NULL,NULL,'Rossi autoctoni: 1) Plant Robert - varietà storica, principalmente nel Lavaux. 2) Servagnin - antico clone Pinot Noir protetto a Morges (La Côte), con denominazione Servagnin de Morges. Bianchi autoctoni: 1) Doral (Chasselas x Chardonnay) - Lavaux e La Côte. 2) Charmont - presente in alcune zone del Vaud. Tutti in piccole quantità, in fase di recupero.',NULL,'Rossi: Plant Robert (Lavaux), Servagnin (Morges/La Côte). Bianchi: Doral (Lavaux/La Côte), Charmont. Tutti in piccole quantità, in recupero.'),
('VAUD','elenco','Elenca le 6 AOC regionali del Vaud.',NULL,NULL,'1. AOC Lavaux. 2. AOC La Côte. 3. AOC Chablais. 4. AOC Côtes-de-l''Orbe. 5. AOC Bonvillars. 6. AOC Vully (condivisa con Friburgo).',NULL,'Lavaux, La Côte, Chablais, Côtes-de-l''Orbe, Bonvillars, Vully (condivisa con Friburgo).'),
('VAUD','elenco','Elenca i 3 Grand Cru AOC del Vaud con le loro caratteristiche.',NULL,NULL,'1. AOC Grand Cru Dézaley (Lavaux): roccia poudingue e marne, Chasselas opulenti longevi 20-30 anni. 2. AOC Grand Cru Calamin (Lavaux): vini più eleganti e floreali. 3. AOC Dézaley-Marsens Grand Cru (Lavaux): parcella storica specifica.',NULL,'Dézaley (Lavaux, poudingue, longevo 20-30 anni), Calamin (Lavaux, elegante), Dézaley-Marsens (parcella storica).'),
('VAUD','elenco','Elenca i vitigni autoctoni del Vaud (bianchi e rossi).',NULL,NULL,'Rossi autoctoni: Plant Robert, Servagnin (clone antico Pinot Noir di Morges). Bianchi autoctoni: Doral (Chasselas x Chardonnay), Charmont.',NULL,'Rossi: Plant Robert, Servagnin. Bianchi: Doral, Charmont.'),
('VAUD','classifica_colore','Classifica questi vitigni del Vaud tra bianchi e rossi:',NULL,'{"Chasselas":"Bianco","Doral":"Bianco","Plant Robert":"Rosso","Servagnin":"Rosso","Charmont":"Bianco","Gamay":"Rosso","Pinot Noir":"Rosso","Chardonnay":"Bianco"}',NULL,'["Chasselas","Doral","Plant Robert","Servagnin","Charmont","Gamay","Pinot Noir","Chardonnay"]','I bianchi autoctoni del Vaud sono Doral e Charmont. I rossi autoctoni sono Plant Robert e Servagnin.'),
('VAUD','classifica_colore','Classifica questi elementi del Vaud come vitigno bianco, vitigno rosso o denominazione/menzione:',NULL,'{"Chasselas":"Bianco","Dorin":"Menzione/Denominazione","Salvagnin":"Menzione/Denominazione","Doral":"Bianco","Plant Robert":"Rosso","Lauriers d Or Terravin":"Menzione/Denominazione","Servagnin":"Rosso"}',NULL,'["Chasselas","Dorin","Salvagnin","Doral","Plant Robert","Lauriers d Or Terravin","Servagnin"]','Nel Vaud bisogna distinguere vitigni (Chasselas, Doral, Plant Robert, Servagnin) dalle menzioni (Dorin, Salvagnin, Lauriers d''Or Terravin).'),
('VAUD','abbinamento','Abbina ogni sottozona del Vaud alla sua caratteristica più importante:',NULL,'{"Lavaux":"UNESCO, tre soli, Grand Cru Dézaley e Calamin","La Côte":"La più grande sottozona, suoli alluvionali, Servagnin de Morges","Chablais":"Confine col Vallese, vento Föhn, Chasselas strutturati","Nord Vaudois (Bonvillars, Côtes-de-l Orbe, Vully)":"Zone fresche ai piedi del Giura, bise, Chasselas leggeri"}',NULL,'{"sx":["Lavaux","La Côte","Chablais","Nord Vaudois (Bonvillars, Côtes-de-l Orbe, Vully)"],"dx":["UNESCO, tre soli, Grand Cru Dézaley e Calamin","La più grande sottozona, suoli alluvionali, Servagnin de Morges","Confine col Vallese, vento Föhn, Chasselas strutturati","Zone fresche ai piedi del Giura, bise, Chasselas leggeri"]}','Ogni sottozona del Vaud ha un microclima distinto che influenza lo stile del Chasselas.'),
('VAUD','abbinamento','Abbina ogni menzione/denominazione del Vaud alla sua descrizione:',NULL,'{"Dorin":"Menzione storica per il Chasselas del Vaud","Salvagnin":"Blend Pinot Noir + Gamay, vino rosso tradizionale","Servagnin de Morges":"Clone antico Pinot Noir con regole su resa e invecchiamento","Lauriers d Or Terravin":"Etichetta qualità per vini selezionati da degustazione","Grand Cru Dézaley":"AOC su roccia poudingue, Chasselas longevo 20-30 anni"}',NULL,'{"sx":["Dorin","Salvagnin","Servagnin de Morges","Lauriers d Or Terravin","Grand Cru Dézaley"],"dx":["Menzione storica per il Chasselas del Vaud","Blend Pinot Noir + Gamay, vino rosso tradizionale","Clone antico Pinot Noir con regole su resa e invecchiamento","Etichetta qualità per vini selezionati da degustazione","AOC su roccia poudingue, Chasselas longevo 20-30 anni"]}','Le menzioni e denominazioni del Vaud hanno significati precisi e disciplinari distinti.'),
('VAUD','comuni','Il Grand Cru Dézaley si trova nel territorio di quali comuni del Lavaux?','{"a":"Morges e Rolle","b":"Epesses e Rivaz","c":"Nyon e Gland","d":"Aigle e Yvorne"}','"b"',NULL,NULL,'Il Grand Cru Dézaley si trova nel territorio dei comuni di Epesses e Rivaz, nel cuore del Lavaux UNESCO, tra Lausanne e Vevey.'),
('VAUD','comuni','In quale comune del Vaud si produce il Servagnin de Morges?','{"a":"Lavaux","b":"Aigle","c":"Morges","d":"Nyon"}','"c"',NULL,NULL,'Il Servagnin de Morges è riservato al clone antico di Pinot Noir coltivato a Morges, nella zona de La Côte, con regole stringenti su resa e invecchiamento.'),
('VAUD','comuni','Quale città del Vaud è circondata dai vigneti del Lavaux ed è sede dell''amministrazione cantonale?','{"a":"Nyon","b":"Vevey","c":"Aigle","d":"Lausanne"}','"d"',NULL,NULL,'Lausanne, capoluogo del canton Vaud, è circondata dai vigneti del Lavaux. Ospita anche il Musée Olympique e la sede del CIO.'),
('GINEVRA','multipla','Quanti ettari ha il cantone di Ginevra e quale posto occupa tra i cantoni svizzeri?','{"a":"800 Ha, 4°","b":"1.200 Ha, 3°","c":"1.400 Ha, 3°","d":"2.000 Ha, 2°"}','"c"',NULL,NULL,'Ginevra ha 1.400 Ha, terzo cantone svizzero per superficie vitata dopo Vallese e Vaud.'),
('GINEVRA','multipla','Quale vento a Ginevra riduce i rischi di gelate primaverili e grandine?','{"a":"Föhn","b":"Joran","c":"Bise","d":"Tramontana"}','"c"',NULL,NULL,'La bise è il vento tipico del cantone di Ginevra. Freddo e secco da nord-est, riduce gelate primaverili e grandine.'),
('GINEVRA','multipla','Quante ore di sole annue ha il cantone di Ginevra?','{"a":"1.600","b":"1.800","c":"2.000","d":"2.200"}','"c"',NULL,NULL,'Ginevra ha circa 2.000 ore di sole annue con circa 900 mm di precipitazioni.'),
('GINEVRA','multipla','Quale comune è il vigneto più esteso della Svizzera?','{"a":"Bernex","b":"Dardagny","c":"Satigny","d":"Meinier"}','"c"',NULL,NULL,'Satigny, nella riva destra del Rodano, è il comune viticolo più esteso di tutta la Svizzera.'),
('GINEVRA','multipla','Qual è la menzione speciale per i vini rossi di qualità di Ginevra con almeno 50% di Gamay?','{"a":"Dorin de Genève","b":"Esprit de Genève","c":"Coteaux de Peney","d":"Mandement de Jussy"}','"b"',NULL,NULL,'L''Esprit de Genève è la menzione per rossi con almeno 50% Gamay e max 20% altri vitigni esclusi Gamay, Gamaret, Garanoir. Prevede controlli su resa, alcol e degustazione.'),
('GINEVRA','multipla','Quale percentuale della produzione vinicola di Ginevra è rappresentata da vini rossi?','{"a":"44%","b":"50%","c":"56%","d":"70%"}','"c"',NULL,NULL,'Ginevra produce il 56% di vini rossi e 44% di bianchi. Gamay è il vitigno più piantato (20%), seguito dal Chasselas (19%).'),
('GINEVRA','multipla','Gamaret e Garanoir sono due incroci svizzeri coltivati a Ginevra. Di che colore sono?','{"a":"Entrambi bianchi","b":"Gamaret rosso, Garanoir bianco","c":"Entrambi rossi","d":"Entrambi rosati"}','"c"',NULL,NULL,'Gamaret e Garanoir sono entrambi rossi, incroci svizzeri sviluppati dall''Agroscope di Changins. Resistenti alle malattie fungine.'),
('GINEVRA','multipla','Quante AOC Premier Cru ha il cantone di Ginevra?','{"a":"10","b":"15","c":"22","d":"30"}','"c"',NULL,NULL,'Ginevra ha 1 AOC cantonale (AOC Genève) e 22 AOC Premier Cru per aree specifiche del cantone.'),
('GINEVRA','multipla','In quale zona di Ginevra si trova il Premier Cru Mandement de Jussy?','{"a":"Riva destra del Rodano (Satigny)","b":"Tra Arve e Rodano (Bernex)","c":"Tra Arve e Lago (Meinier)","d":"Riva sinistra del Lago"}','"c"',NULL,NULL,'Il Premier Cru Mandement de Jussy si trova nella zona tra Arve e Lago di Ginevra, vicino al comune di Meinier.'),
('GINEVRA','multipla','Il cantone di Ginevra ha vitigni autoctoni propri?','{"a":"Sì, il Gamaret","b":"Sì, il Chasselas ginevrino","c":"No, si concentra su vitigni internazionali e incroci svizzeri","d":"Sì, il Garanoir"}','"c"',NULL,NULL,'Ginevra non ha vitigni autoctoni. La produzione si concentra su vitigni internazionali (Gamay, Chasselas, Pinot Noir, Chardonnay) e incroci svizzeri recenti (Gamaret, Garanoir).'),
('GINEVRA','vero_falso','Il cantone di Ginevra ha circa 1.400 Ha di vigneti e l''85% è meccanizzabile.',NULL,'true',NULL,NULL,'Vero. Territorio leggermente collinare tra 400 e 500 m s.l.m. con suoli morenichi e alluvionali. L''85% dei vigneti è meccanizzabile.'),
('GINEVRA','vero_falso','L''Esprit de Genève ammette fino al 50% di vitigni diversi dal Gamay nel blend.',NULL,'false',NULL,NULL,'Falso. L''Esprit de Genève prevede minimo 50% Gamay e MASSIMO 20% di altri vitigni (esclusi Gamay, Gamaret, Garanoir).'),
('GINEVRA','vero_falso','I suoli del cantone di Ginevra sono principalmente morenichi e alluvionali lasciati dai fiumi Rodano e Arve.',NULL,'true',NULL,NULL,'Vero. Suoli principalmente morenichi e alluvionali con alto contenuto di calcare, lasciati dall''attività glaciale e dai fiumi Rodano e Arve.'),
('GINEVRA','vero_falso','La riva destra del Rodano con Satigny e Dardagny è la zona vinicola più piccola del cantone.',NULL,'false',NULL,NULL,'Falso. La riva destra del Rodano è la zona più GRANDE del cantone di Ginevra, ospitando Satigny, il comune viticolo più esteso della Svizzera.'),
('GINEVRA','vero_falso','Il Gamay è il vitigno più piantato nel cantone di Ginevra con circa il 20% della superficie.',NULL,'true',NULL,NULL,'Vero. Il Gamay è il più piantato a Ginevra (20%), seguito dal Chasselas (19%). Insieme coprono quasi il 40% della superficie vitata.'),
('GINEVRA','vero_falso','Le montagne del Giura a ovest di Ginevra deviano le perturbazioni atmosferiche favorendo la viticoltura.',NULL,'true',NULL,NULL,'Vero. Il Giura a ovest protegge Ginevra da molte perturbazioni, contribuendo a circa 900 mm di precipitazioni e 2.000 ore di sole.'),
('GINEVRA','aperta','Descrivi le tre zone viticole del cantone di Ginevra e le loro caratteristiche principali.',NULL,NULL,'1. Riva destra del Rodano (Satigny, Dardagny): la più grande area vinicola, Satigny è il comune viticolo più esteso della Svizzera. Suoli alluvionali tra Rodano e Giura. 2. Tra Arve e Rodano (Bernex, Bardonnex): zona urbana a sud della città, suoli morenichi e alluvionali. 3. Tra Arve e Lago (Meinier): zona est, vicino al lago, Premier Cru Mandement de Jussy.',NULL,'1. Riva destra Rodano (Satigny, Dardagny): più grande, Satigny più esteso CH. 2. Tra Arve e Rodano (Bernex): zona urbana, suoli morenichi. 3. Tra Arve e Lago (Meinier): est, Premier Cru Mandement de Jussy.'),
('GINEVRA','aperta','Descrivi la struttura AOC del cantone di Ginevra e la menzione Esprit de Genève.',NULL,NULL,'Il cantone di Ginevra ha 1 AOC cantonale (AOC Genève) e 22 AOC Premier Cru per aree specifiche. La menzione Esprit de Genève è riservata ai rossi con: minimo 50% Gamay, massimo 20% altri vitigni (esclusi Gamay, Gamaret, Garanoir), vincoli su resa per ettaro, grado alcolico e vite, superamento di un assaggio da commissione.',NULL,'1 AOC cantonale + 22 AOC Premier Cru. Esprit de Genève: min 50% Gamay, max 20% altri vitigni, controlli su resa/alcol, commissione di degustazione.'),
('GINEVRA','aperta','Descrivi il clima del cantone di Ginevra e il ruolo del vento bise.',NULL,NULL,'Il cantone di Ginevra ha un clima omogeneo mitigato dal Lago Lemano. Le montagne del Giura a ovest deviano le perturbazioni. Il vento bise (freddo e secco da nord-est) riduce i rischi di gelate primaverili e grandine, asciugando l''aria attorno ai grappoli. Circa 900 mm di precipitazioni e 2.000 ore di sole annue.',NULL,'Clima omogeneo mitigato dal Lemano. Giura protegge a ovest. Bise (freddo, secco da NE) riduce gelate e grandine. ~900 mm pioggia, ~2.000 ore sole.'),
('GINEVRA','aperta','Perché Satigny è importante nel panorama viticolo svizzero?',NULL,NULL,'Satigny è il comune viticolo più esteso di tutta la Svizzera. Si trova nella Riva Destra del Rodano, la zona viticola più grande del cantone di Ginevra, tra il fiume Rodano e le colline del Giura. La grande estensione dei vigneti riflette l''85% di meccanizzabilità dei vigneti ginevrini, grazie al terreno dolcemente collinare tra 400 e 500 m s.l.m.',NULL,'Satigny: comune viticolo più esteso della Svizzera. Riva destra del Rodano (zona più grande di GE). Terreno pianeggiante, 85% meccanizzabile.'),
('GINEVRA','elenco','Elenca i vitigni rossi coltivati nel cantone di Ginevra.',NULL,NULL,'Gamay (20%, il più piantato), Pinot Noir, Gamaret (incrocio svizzero rosso), Garanoir (incrocio svizzero rosso), Merlot.',NULL,'Gamay (20%), Pinot Noir, Gamaret, Garanoir, Merlot.'),
('GINEVRA','elenco','Elenca i vitigni bianchi coltivati nel cantone di Ginevra.',NULL,NULL,'Chasselas (19%, il più piantato tra i bianchi), Chardonnay, Pinot Blanc, Sauvignon Blanc.',NULL,'Chasselas (19%), Chardonnay, Pinot Blanc, Sauvignon Blanc.'),
('GINEVRA','elenco','Elenca le 3 zone viticole del cantone di Ginevra con almeno un comune per zona.',NULL,NULL,'1. Riva destra del Rodano: Satigny, Dardagny. 2. Tra Arve e Rodano: Bernex, Bardonnex. 3. Tra Arve e Lago di Ginevra: Meinier.',NULL,'1. Riva destra Rodano: Satigny, Dardagny. 2. Tra Arve e Rodano: Bernex, Bardonnex. 3. Tra Arve e Lago: Meinier.'),
('GINEVRA','classifica_colore','Classifica questi vitigni coltivati a Ginevra tra bianchi e rossi:',NULL,'{"Gamay":"Rosso","Chasselas":"Bianco","Gamaret":"Rosso","Pinot Noir":"Rosso","Chardonnay":"Bianco","Garanoir":"Rosso","Merlot":"Rosso","Sauvignon Blanc":"Bianco"}',NULL,'["Gamay","Chasselas","Gamaret","Pinot Noir","Chardonnay","Garanoir","Merlot","Sauvignon Blanc"]','Gamaret e Garanoir sono incroci svizzeri a bacca rossa. Chasselas, Chardonnay e Sauvignon Blanc sono bianchi.'),
('GINEVRA','classifica_colore','Classifica come vitigno bianco, vitigno rosso o denominazione/menzione di Ginevra:',NULL,'{"Gamay":"Rosso","Esprit de Genève":"Menzione/Denominazione","Chasselas":"Bianco","AOC Premier Cru":"Menzione/Denominazione","Gamaret":"Rosso","Bise":"Altro (vento)","Satigny":"Altro (comune)"}',NULL,'["Gamay","Esprit de Genève","Chasselas","AOC Premier Cru","Gamaret","Bise","Satigny"]','Saper distinguere vitigni, menzioni e altri elementi del cantone di Ginevra è fondamentale per l''esame.'),
('GINEVRA','abbinamento','Abbina ogni area di Ginevra alla sua descrizione:',NULL,'{"Riva destra del Rodano (Satigny, Dardagny)":"La zona più grande, Satigny è il comune più esteso di Svizzera","Tra Arve e Rodano (Bernex, Bardonnex)":"Zona urbana sud, suoli morenichi e alluvionali","Tra Arve e Lago (Meinier)":"Zona est, Premier Cru Mandement de Jussy"}',NULL,'{"sx":["Riva destra del Rodano (Satigny, Dardagny)","Tra Arve e Rodano (Bernex, Bardonnex)","Tra Arve e Lago (Meinier)"],"dx":["La zona più grande, Satigny è il comune più esteso di Svizzera","Zona urbana sud, suoli morenichi e alluvionali","Zona est, Premier Cru Mandement de Jussy"]}','Le tre zone di Ginevra sono definite geograficamente dai due fiumi principali (Rodano e Arve) e dal lago.'),
('GINEVRA','abbinamento','Abbina ogni vitigno/termine di Ginevra alla sua definizione:',NULL,'{"Gamay":"Vitigno rosso più piantato a Ginevra (20%)","Gamaret":"Incrocio svizzero rosso resistente alle malattie","Esprit de Genève":"Menzione qualità per rossi con min 50% Gamay","Bise":"Vento freddo che riduce gelate e grandine","Satigny":"Comune viticolo più esteso della Svizzera"}',NULL,'{"sx":["Gamay","Gamaret","Esprit de Genève","Bise","Satigny"],"dx":["Vitigno rosso più piantato a Ginevra (20%)","Incrocio svizzero rosso resistente alle malattie","Menzione qualità per rossi con min 50% Gamay","Vento freddo che riduce gelate e grandine","Comune viticolo più esteso della Svizzera"]}','Conoscere il ruolo di ogni elemento nella viticoltura ginevrина è essenziale per l''esame.'),
('GINEVRA','comuni','Quale Premier Cru è associato al comune di Dardagny?','{"a":"Mandement de Jussy","b":"Coteaux de Peney","c":"Coteaux de Dardagny","d":"Domaine des Rueyres"}','"c"',NULL,NULL,'Le Coteaux de Dardagny sono il Premier Cru del comune di Dardagny, nella riva destra del Rodano, zona più importante del cantone.'),
('GINEVRA','comuni','Il comune di Bernex si trova in quale zona viticola di Ginevra?','{"a":"Riva destra del Rodano","b":"Tra Arve e Rodano","c":"Tra Arve e Lago","d":"Riva sinistra del Lemano"}','"b"',NULL,NULL,'Bernex si trova nella zona tra Arve e Rodano, la zona urbana a sud della città di Ginevra, con suoli morenichi e alluvionali.'),
('GINEVRA','comuni','Come si chiama il Premier Cru nella zona tra Arve e Lago, comune di Meinier?','{"a":"Coteaux de Peney","b":"Coteaux de Dardagny","c":"Mandement de Jussy","d":"Dorin de Peissy"}','"c"',NULL,NULL,'Il Premier Cru Mandement de Jussy si trova nel comune di Meinier, nella zona tra Arve e Lago di Ginevra, la zona est del cantone.'),
('TRE_LAGHI','multipla','Quanti ettari ha la regione dei Tre Laghi?','{"a":"600 Ha","b":"900 Ha","c":"1.200 Ha","d":"1.500 Ha"}','"b"',NULL,NULL,'La regione dei Tre Laghi ha circa 900 Ha di vigneti, suddivisi tra Neuchâtel, Berna e Friburgo.'),
('TRE_LAGHI','multipla','Quali sono i tre laghi che danno il nome alla regione?','{"a":"Lemano, Lugano, Maggiore","b":"Neuchâtel, Bienna (Bienne), Morat (Murten)","c":"Costanza, Zurigo, Zugo","d":"Thun, Brienz, Sarnen"}','"b"',NULL,NULL,'La regione Trois Lacs prende il nome dai laghi di Neuchâtel, Bienna (Bienne) e Morat (Murten).'),
('TRE_LAGHI','multipla','Qual è il vitigno più piantato nella regione dei Tre Laghi?','{"a":"Chasselas","b":"Chardonnay","c":"Pinot Noir","d":"Gamaret"}','"c"',NULL,NULL,'Il Pinot Noir è il vitigno principale dei Tre Laghi con circa il 49% della superficie, seguito dal Chasselas al 28%.'),
('TRE_LAGHI','multipla','Come si chiama il rosato tipico di Neuchâtel da Pinot Noir con macerazione breve?','{"a":"Perdrix Blanche","b":"Non Filtré","c":"Oeil de Perdrix","d":"Gerle d''Or"}','"c"',NULL,NULL,'L''Oeil de Perdrix (occhio di pernice) è il rosato tipico di Neuchâtel da Pinot Nero con macerazione breve.'),
('TRE_LAGHI','multipla','Da quando viene commercializzato il Non Filtré di Neuchâtel ogni anno?','{"a":"3° giovedì di novembre","b":"3° mercoledì di gennaio","c":"1° marzo","d":"11 novembre (San Martino)"}','"b"',NULL,NULL,'Il Non Filtré (Chasselas non filtrato, dal 1995) viene commercializzato dal terzo mercoledì di gennaio.'),
('TRE_LAGHI','multipla','Come si chiama il vento freddo dal Giura tipico del cantone di Neuchâtel?','{"a":"Bise","b":"Föhn","c":"Joran","d":"Vent du Lac"}','"c"',NULL,NULL,'Il Joran è il vento forte e freddo dal Giura tipico del Neuchâtel. Obbliga i viticoltori ad usare fili di sostegno per le viti.'),
('TRE_LAGHI','multipla','La Perdrix Blanche è una specialità di Neuchâtel. Di cosa si tratta?','{"a":"Un Chasselas non filtrato","b":"Un Pinot Nero vinificato in bianco (blanc de noirs)","c":"Un rosato frizzante","d":"Un dolce da uve botritizzate"}','"b"',NULL,NULL,'La Perdrix Blanche è il Pinot Nero vinificato in bianco (blanc de noirs), etichetta protetta e specialità locale di Neuchâtel.'),
('TRE_LAGHI','multipla','La Gerle d''Or è un''etichetta di Neuchâtel. Cosa premia?','{"a":"I migliori Pinot Noir della regione","b":"I migliori Chasselas AOC selezionati per qualità","c":"I vini rosati Oeil de Perdrix di annata","d":"I produttori biologici certificati"}','"b"',NULL,NULL,'La Gerle d''Or è un''etichetta di qualità attribuita ai migliori Chasselas AOC di Neuchâtel, selezionati da commissione di degustatori.'),
('TRE_LAGHI','multipla','L''AOC Vully è condivisa tra quali cantoni?','{"a":"Neuchâtel e Berna","b":"Vaud e Friburgo","c":"Berna e Friburgo","d":"Neuchâtel e Friburgo"}','"b"',NULL,NULL,'L''AOC Vully è condivisa tra il cantone Vaud e il cantone Friburgo.'),
('TRE_LAGHI','multipla','Quale nome regionale ha il Gewürztraminer nel cantone di Friburgo?','{"a":"Traminer","b":"Épicé","c":"Savagnin Rose","d":"Freisamer"}','"a"',NULL,NULL,'Nel cantone di Friburgo il Gewürztraminer è tradizionalmente chiamato Traminer. Il Freisamer è un altro vitigno bianco locale (Freiburger).'),
('TRE_LAGHI','vero_falso','Il Pinot Noir copre circa il 49% della superficie vitata della regione dei Tre Laghi.',NULL,'true',NULL,NULL,'Vero. Il Pinot Noir è il vitigno dominante dei Tre Laghi con il 49%, seguito dal Chasselas al 28%. La regione produce il 56% di rossi.'),
('TRE_LAGHI','vero_falso','La Perdrix Blanche è una varietà di Pinot Nero con buccia più chiara.',NULL,'false',NULL,NULL,'Falso. La Perdrix Blanche non è una varietà separata ma un Pinot Nero normale vinificato in bianco: il succo viene separato immediatamente dalla buccia senza macerazione.'),
('TRE_LAGHI','vero_falso','Il Non Filtré di Neuchâtel esiste dal 1995 ed è commercializzato ogni anno dal terzo mercoledì di gennaio.',NULL,'true',NULL,NULL,'Vero. Il Non Filtré è un Chasselas non filtrato prodotto dal 1995, commercializzato dal terzo mercoledì di gennaio come vino giovane e fresco.'),
('TRE_LAGHI','vero_falso','La regione dei Tre Laghi ha vitigni autoctoni come il Räuschling e il Completer.',NULL,'false',NULL,NULL,'Falso. La regione non ha vitigni autoctoni propri. Räuschling è di Zurigo e Completer è dei Grigioni. I Tre Laghi sono specializzati in Pinot Noir e Chasselas.'),
('TRE_LAGHI','vero_falso','Il Joran obbliga i viticoltori di Neuchâtel ad allevare le viti con fili di sostegno per proteggerle.',NULL,'true',NULL,NULL,'Vero. Il Joran è un vento forte e freddo dal Giura che può danneggiare le viti. Per questo i viticoltori di Neuchâtel usano spesso fili di sostegno.'),
('TRE_LAGHI','vero_falso','La regione dei Tre Laghi ha 4 AOC regionali inclusa l''AOC Vully condivisa con il Vaud.',NULL,'true',NULL,NULL,'Vero. Le 4 AOC regionali dei Tre Laghi sono: AOC Neuchâtel, AOC Lac de Bienne, AOC Vully (condivisa con Vaud), AOC Cheyres.'),
('TRE_LAGHI','aperta','Descrivi le specialità enologiche del cantone di Neuchâtel (almeno 4).',NULL,NULL,'1. Oeil de Perdrix: rosato da Pinot Nero con macerazione breve, colore rosa tenue. 2. Perdrix Blanche: Pinot Nero vinificato in bianco (blanc de noirs), etichetta protetta. 3. Non Filtré: Chasselas non filtrato, dal 1995, commercializzato dal 3° mercoledì di gennaio. 4. Gerle d''Or: marchio di qualità per i migliori Chasselas AOC selezionati per degustazione.',NULL,'Oeil de Perdrix (rosato Pinot Nero), Perdrix Blanche (PN in bianco), Non Filtré (Chasselas non filtrato da gennaio), Gerle d''Or (qualità per migliori Chasselas).'),
('TRE_LAGHI','aperta','Descrivi la struttura delle AOC della regione dei Tre Laghi (cantoni e denominazioni).',NULL,NULL,'4 AOC regionali: AOC Neuchâtel (cantone Neuchâtel), AOC Lac de Bienne (cantone Berna), AOC Vully (condivisa Vaud e Friburgo), AOC Cheyres (cantone Friburgo). Specialità di Neuchâtel: Oeil de Perdrix, Perdrix Blanche, Non Filtré, Gerle d''Or.',NULL,'AOC Neuchâtel (NE), AOC Lac de Bienne (BE), AOC Vully (VD+FR), AOC Cheyres (FR). Specialità NE: Oeil de Perdrix, Perdrix Blanche, Non Filtré, Gerle d''Or.'),
('TRE_LAGHI','aperta','Descrivi il clima della regione dei Tre Laghi e l''impatto del vento Joran.',NULL,NULL,'Il clima è moderato dall''influenza dei tre laghi (Neuchâtel, Bienna, Morat) e dal massiccio del Giura. Circa 1.100 mm di precipitazioni e 1.800 ore di sole. Altitudine tra 430 e 600 m s.l.m. Il Joran, vento forte e freddo dal Giura, è un rischio specifico per la zona di Neuchâtel: obbliga i viticoltori ad usare fili di sostegno per proteggere le viti dalle raffiche.',NULL,'Clima moderato dai tre laghi, ~1.100 mm pioggia, ~1.800 ore sole. Joran: vento freddo dal Giura che richiede fili di sostegno per le viti nel Neuchâtel.'),
('TRE_LAGHI','aperta','Come si differenziano i vini dell''AOC Neuchâtel da quelli dell''AOC Lac de Bienne?',NULL,NULL,'AOC Neuchâtel: principalmente Pinot Noir e Chasselas, famoso per Oeil de Perdrix, Perdrix Blanche e Non Filtré. Suoli calcarei e sassosi. AOC Lac de Bienne (cantone Berna): stesso orientamento ma vini tendenzialmente più freschi e strutturati per la latitudine più settentrionale e l''influenza del lago di Bienne.',NULL,'Neuchâtel: Oeil de Perdrix, Perdrix Blanche, Non Filtré, Gerle d''Or. Lac de Bienne: stessi vitigni ma più fresco e strutturato per latitudine più a nord.'),
('TRE_LAGHI','elenco','Elenca le 4 AOC regionali dei Tre Laghi con il relativo cantone.',NULL,NULL,'1. AOC Neuchâtel (cantone Neuchâtel). 2. AOC Lac de Bienne (cantone Berna). 3. AOC Vully (cantoni Vaud e Friburgo, condivisa). 4. AOC Cheyres (cantone Friburgo).',NULL,'AOC Neuchâtel (NE), AOC Lac de Bienne (BE), AOC Vully (VD+FR), AOC Cheyres (FR).'),
('TRE_LAGHI','elenco','Elenca tutte le menzioni e specialità enologiche protette del cantone di Neuchâtel.',NULL,NULL,'Oeil de Perdrix (rosato da Pinot Nero), Perdrix Blanche (Pinot Nero vinificato in bianco, etichetta protetta), Non Filtré (Chasselas non filtrato, dal 3° mercoledì di gennaio), Gerle d''Or (etichetta di qualità per migliori Chasselas AOC).',NULL,'Oeil de Perdrix, Perdrix Blanche, Non Filtré, Gerle d''Or.'),
('TRE_LAGHI','elenco','Elenca i vitigni principali della regione dei Tre Laghi (almeno 4).',NULL,NULL,'Pinot Noir (49% della superficie), Chasselas (28%), Chardonnay, Pinot Gris, Gamaret, Gewürztraminer (Traminer nel Friburgo), Freisamer (Freiburger nel Friburgo).',NULL,'Pinot Noir (49%), Chasselas (28%), Chardonnay, Pinot Gris, Gamaret, Gewürztraminer/Traminer, Freisamer.'),
('TRE_LAGHI','classifica_colore','Classifica questi vitigni della regione dei Tre Laghi:',NULL,'{"Pinot Noir":"Rosso","Chasselas":"Bianco","Gamaret":"Rosso","Chardonnay":"Bianco","Pinot Gris":"Bianco","Gewürztraminer":"Bianco","Freisamer":"Bianco","Regent":"Rosso"}',NULL,'["Pinot Noir","Chasselas","Gamaret","Chardonnay","Pinot Gris","Gewürztraminer","Freisamer","Regent"]','Il Freisamer è un vitigno bianco chiamato Freiburger a Friburgo. Il Regent è un incrocio tedesco a bacca rossa resistente alle malattie.'),
('TRE_LAGHI','classifica_colore','Classifica questi termini come bianco, rosso o specialità dei Tre Laghi:',NULL,'{"Oeil de Perdrix":"Specialità (rosato)","Pinot Noir":"Rosso","Perdrix Blanche":"Specialità (blanc de noirs)","Chasselas":"Bianco","Non Filtré":"Specialità (Chasselas giovane)","Gerle d Or":"Specialità (etichetta qualità)"}',NULL,'["Oeil de Perdrix","Pinot Noir","Perdrix Blanche","Chasselas","Non Filtré","Gerle d Or"]','Distinguere i vitigni dalle specialità di Neuchâtel è fondamentale. Oeil de Perdrix è rosato, Perdrix Blanche è bianco da PN, Non Filtré è Chasselas giovane.'),
('TRE_LAGHI','abbinamento','Abbina ogni specialità di Neuchâtel alla sua descrizione:',NULL,'{"Oeil de Perdrix":"Rosato da Pinot Nero con macerazione breve, colore rosa tenue","Perdrix Blanche":"Pinot Nero vinificato in bianco (blanc de noirs), etichetta protetta","Non Filtré":"Chasselas non filtrato, commercializzato dal 3° mercoledì di gennaio","Gerle d Or":"Etichetta di qualità per i migliori Chasselas AOC selezionati da esperti"}',NULL,'{"sx":["Oeil de Perdrix","Perdrix Blanche","Non Filtré","Gerle d Or"],"dx":["Rosato da Pinot Nero con macerazione breve, colore rosa tenue","Pinot Nero vinificato in bianco (blanc de noirs), etichetta protetta","Chasselas non filtrato, commercializzato dal 3° mercoledì di gennaio","Etichetta di qualità per i migliori Chasselas AOC selezionati da esperti"]}','Le quattro specialità di Neuchâtel sono tutte importanti per l''esame ASPI.'),
('TRE_LAGHI','abbinamento','Abbina ogni cantone dei Tre Laghi alla sua AOC principale:',NULL,'{"Neuchâtel":"AOC Neuchâtel","Berna":"AOC Lac de Bienne","Friburgo (zona Vully)":"AOC Vully (condivisa con Vaud)","Friburgo (zona Cheyres)":"AOC Cheyres"}',NULL,'{"sx":["Neuchâtel","Berna","Friburgo (zona Vully)","Friburgo (zona Cheyres)"],"dx":["AOC Neuchâtel","AOC Lac de Bienne","AOC Vully (condivisa con Vaud)","AOC Cheyres"]}','I Tre Laghi si estendono su tre cantoni con quattro AOC regionali distinte.'),
('TRE_LAGHI','comuni','In quale cantone si trova il comune di Neuchâtel, cuore della regione enologica omonima?','{"a":"Friburgo","b":"Berna","c":"Neuchâtel","d":"Vaud"}','"c"',NULL,NULL,'La città di Neuchâtel è il capoluogo del cantone omonimo e il centro della viticoltura della regione.'),
('TRE_LAGHI','comuni','Nell''AOC Lac de Bienne, in quale cantone si trovano i vigneti principali?','{"a":"Friburgo","b":"Neuchâtel","c":"Vaud","d":"Berna"}','"d"',NULL,NULL,'L''AOC Lac de Bienne si trova nel cantone di Berna, sulle rive del lago di Bienne (Biel). La zona più settentrionale dei Tre Laghi.'),
('TRE_LAGHI','comuni','Quale zona dei Tre Laghi è famosa per il Gewürztraminer chiamato Traminer e per il Freisamer (Freiburger)?','{"a":"AOC Neuchâtel","b":"AOC Lac de Bienne","c":"AOC Cheyres (Friburgo)","d":"AOC Vully"}','"c"',NULL,NULL,'La zona dell''AOC Cheyres nel cantone di Friburgo è nota per il Gewürztraminer (Traminer) e il Freisamer (Freiburger), vitigni bianchi aromatici tipici della zona.'),
('TICINO','multipla','Quale percentuale della produzione ticinese è rappresentata dai vini rossi?','{"a":"70%","b":"80%","c":"89%","d":"95%"}','"c"',NULL,NULL,'Il Ticino produce l''89% di vini rossi e solo l''11% di bianchi. Il Merlot da solo copre circa l''80% della superficie vitata.'),
('TICINO','multipla','Come è diviso il Ticino dal Monte Ceneri?','{"a":"In Sopraceneri (nord) e Sottoceneri (sud)","b":"In Ticino Orientale e Occidentale","c":"In Alta Valle e Bassa Valle","d":"In Ticino Urbano e Rurale"}','"a"',NULL,NULL,'Il Monte Ceneri divide il Ticino in Sopraceneri (nord: Bellinzona, Locarno) con suoli granitici, e Sottoceneri (sud: Lugano, Mendrisiotto) con suoli morenichi.'),
('TICINO','multipla','Cosa è il Merlot Bianco ticinese?','{"a":"Un Merlot rosato","b":"Un blanc de noirs da Merlot","c":"Un incrocio Merlot e Pinot Grigio","d":"Un Merlot dolce da uve passite"}','"b"',NULL,NULL,'Il Merlot Bianco è un blanc de noirs da uve Merlot: uve rosse pressate senza macerazione, producendo un vino bianco con i profumi del Merlot.'),
('TICINO','multipla','Cosa richiede la menzione Riserva nell''AOC Ticino per i vini rossi?','{"a":"6 mesi in barrique","b":"Millesimo obbligatorio e almeno 18 mesi di invecchiamento","c":"Solo uve da singola vigna","d":"12 mesi in legno e 6 in bottiglia"}','"b"',NULL,NULL,'La menzione Riserva nell''AOC Ticino richiede millesimo obbligatorio e invecchiamento minimo di 18 mesi per i rossi (12 mesi per i bianchi).'),
('TICINO','multipla','Quale IGT è presente in Ticino e include la IGT Nostrano?','{"a":"IGT Ticino","b":"Svizzera Italiana IGT","c":"IGT Confederazione","d":"Ticino Rosso IGT"}','"b"',NULL,NULL,'La Svizzera Italiana IGT è l''indicazione geografica tipica del Ticino, che include la IGT Nostrano.'),
('TICINO','multipla','Cos''è il Merlot Viti in Ticino?','{"a":"Il clone di Merlot più comune nel cantone","b":"Un''etichetta di qualità per vini Merlot gestita da 18 produttori","c":"Un disciplinare per il Merlot biologico","d":"Un vino rosato da Merlot con invecchiamento"}','"b"',NULL,NULL,'Il Merlot Viti è un''etichetta di qualità per Merlot rossi del Ticino, gestita da 18 produttori. Richiede almeno 1 anno di invecchiamento e degustazione ufficiale.'),
('TICINO','multipla','Qual è il vitigno autoctono rosso del Ticino, oggi quasi scomparso?','{"a":"Americana","b":"Bondola","c":"Nostrano","d":"Isabella"}','"b"',NULL,NULL,'La Bondola è l''unico vitigno autoctono rosso del Ticino. Quasi scomparsa a favore del Merlot, è ora coltivata da alcuni produttori per preservare l''identità locale.'),
('TICINO','multipla','Perché il Ticino è chiamato il solarium della Svizzera?','{"a":"Per i suoi laghi balneabili","b":"Per le circa 2.200 ore di sole annue","c":"Per la produzione di energia solare","d":"Per il microclima caldo del Mendrisiotto"}','"b"',NULL,NULL,'Il Ticino, a sud delle Alpi con forte influenza mediterranea, ha circa 2.200 ore di sole annue, il dato più alto della Svizzera.'),
('TICINO','multipla','Quale caratteristica del Ticino è in contraddizione con il soprannome solarium della Svizzera?','{"a":"Le gelate frequenti in primavera","b":"Il record di precipitazioni svizzere (1.600-1.800 mm/anno)","c":"I venti freddi alpini in estate","d":"L''altitudine media elevata dei vigneti"}','"b"',NULL,NULL,'Nonostante le molte ore di sole, il Ticino detiene il record di precipitazioni svizzere: 1.600-1.800 mm/anno, spesso come intensi temporali con forte rischio grandine.'),
('TICINO','multipla','In quale zona del Ticino si trova il Mendrisiotto, noto per i Merlot di alta qualità?','{"a":"Sopraceneri","b":"Sottoceneri","c":"Valle Leventina","d":"Locarnese"}','"b"',NULL,NULL,'Il Mendrisiotto si trova nel Sottoceneri, la zona sud del Ticino. Suoli morenichi con argilla e calcare producono i Merlot più strutturati del cantone.'),
('TICINO','vero_falso','Nel Sopraceneri i suoli sono principalmente di origine glaciale con granito, gneiss e rocce cristalline.',NULL,'true',NULL,NULL,'Vero. Il Sopraceneri (Bellinzona, Locarno, valli alpine) ha suoli di origine glaciale e fluviale: granito, gneiss, rocce cristalline, sabbia e ghiaia.'),
('TICINO','vero_falso','L''AOC Ticino permette l''indicazione del vitigno solo se supera il 10% del blend.',NULL,'true',NULL,NULL,'Vero. L''AOC Ticino prevede: indicazione vitigno possibile se >10%, indicazione esclusiva solo se >90%.'),
('TICINO','vero_falso','Il Ticino ha una sola AOC regionale chiamata Ticino DOC.',NULL,'true',NULL,NULL,'Vero. Il Ticino ha una sola AOC regionale (Ticino DOC) per rossi, bianchi e rosati. Non esistono AOC locali o comunali separate.'),
('TICINO','vero_falso','Il Merlot Bianco ticinese è un rosato prodotto da Merlot con macerazione brevissima.',NULL,'false',NULL,NULL,'Falso. Il Merlot Bianco è un blanc de noirs: le uve Merlot vengono pressate immediatamente senza alcuna macerazione. È un vino bianco, non rosato.'),
('TICINO','vero_falso','Il Ticino ha anche vitigni americani come Isabella e Americana Rossa, usati principalmente per grappa e uva da tavola.',NULL,'true',NULL,NULL,'Vero. Il Ticino ha circa il 3% di vitigni americani (Americana Rossa, Catawba, Isabella, Rossa da Terza) usati per grappa, acquavite o uva da tavola.'),
('TICINO','vero_falso','L''altitudine dei vigneti ticinesi varia dai 200 m ai 600 m s.l.m.',NULL,'true',NULL,NULL,'Vero. I vigneti ticinesi vanno dai 200 m nelle zone di pianura fino a 600 m nella Valle Leventina e in altre valli alpine del Sopraceneri.'),
('TICINO','aperta','Descrivi le differenze pedologiche tra il Sopraceneri e il Sottoceneri in Ticino.',NULL,NULL,'Sopraceneri (Bellinzona, Locarno, Vallemaggia, Riviera, Blenio): suoli di origine glaciale e fluviale, ricchi di granito, gneiss, rocce cristalline, sabbia e ghiaia. Suoli più acidi e poveri, meno calciferi. Sottoceneri (Lugano, Mendrisiotto, Malcantone): suoli di origine morenica con argilla, sabbia, ghiaia e calcari. Suoli più fertili e ricchi. Entrambe le zone producono prevalentemente Merlot nell''unica AOC regionale.',NULL,'Sopraceneri: suoli glaciali-fluviali, granito, gneiss, rocce cristalline. Sottoceneri: suoli morenichi, argilla, sabbia, calcare. Più fertili e calciferi al sud.'),
('TICINO','aperta','Descrivi la struttura delle denominazioni in Ticino: AOC, IGT, menzioni speciali.',NULL,NULL,'1. Ticino DOC (unica AOC regionale): Rosso, Bianco, Rosato, del Ticino/Ticinese. Indicazione vitigno se >10%, esclusiva se >90%. Riserva: millesimo + min 18 mesi (rossi) o 12 mesi (bianchi). 2. Svizzera Italiana IGT: include IGT Nostrano. 3. Merlot Viti: etichetta qualità per Merlot rossi di 18 produttori, min 1 anno invecchiamento + degustazione ufficiale.',NULL,'Ticino DOC (unica AOC): rosso/bianco/rosato, Riserva (18m rossi, 12m bianchi). Svizzera Italiana IGT + IGT Nostrano. Merlot Viti: etichetta qualità 18 produttori.'),
('TICINO','aperta','Cos''è il Merlot Bianco ticinese? Come si produce e cosa lo rende unico?',NULL,NULL,'Il Merlot Bianco è un blanc de noirs prodotto esclusivamente da uve Merlot. Produzione: le uve Merlot rosse vengono pressate immediatamente dopo la raccolta senza macerazione, separando subito il succo dalle bucce. Il succo, privo di pigmenti rossi, produce un vino bianco con i profumi e la struttura del Merlot (frutto, erbe, spezie dolci). Specialità emblematica del Ticino.',NULL,'Blanc de noirs da Merlot: uve pressate subito senza macerazione. Vino bianco con profumi e struttura del Merlot. Specialità emblematica ticinese.'),
('TICINO','aperta','Descrivi il clima del Ticino e spiega il paradosso del solarium della Svizzera.',NULL,NULL,'Il Ticino è il cantone più a sud, interamente oltre le Alpi con forte influenza mediterranea. Ha circa 2.200 ore di sole annue, le più alte della Svizzera (solarium). Il paradosso: detiene anche il record svizzero di precipitazioni: 1.600-1.800 mm/anno, spesso come violenti temporali estivi con forte rischio grandine. I viticoltori devono proteggersi con reti antigrandine. Il calore favorisce la maturazione del Merlot ma la piovosità richiede attenzione sanitaria.',NULL,'2.200 ore sole (solarium CH). Ma anche record precipitazioni CH: 1.600-1.800 mm/anno, violenti temporali, forte rischio grandine. Necessarie reti antigrandine.'),
('TICINO','elenco','Elenca almeno 5 comuni del Ticino con la loro zona (Sopraceneri o Sottoceneri).',NULL,NULL,'Sopraceneri: Bellinzona, Locarno, Ascona, Riviera, Blenio, Vallemaggia. Sottoceneri: Lugano, Mendrisio, Chiasso, Malcantone, Morcote, Riva San Vitale.',NULL,'Sopraceneri: Bellinzona, Locarno, Ascona, Riviera. Sottoceneri: Lugano, Mendrisio, Chiasso, Malcantone.'),
('TICINO','elenco','Elenca le tipologie di vini dell''AOC Ticino (Ticino DOC) e le regole per le menzioni speciali.',NULL,NULL,'Tipologie: Rosso, Bianco, Rosato, del Ticino/Ticinese. Menzione vitigno: possibile se >10%. Indicazione esclusiva vitigno: solo se >90%. Menzione Riserva: millesimo obbligatorio + min 18 mesi invecchiamento (rossi) o 12 mesi (bianchi).',NULL,'Rosso, Bianco, Rosato. Vitigno se >10%, esclusivo se >90%. Riserva: millesimo + 18m rossi / 12m bianchi.'),
('TICINO','elenco','Elenca i vitigni americani presenti in Ticino e il loro utilizzo.',NULL,NULL,'Vitigni americani in Ticino (~3%): Americana Rossa, Catawba, Isabella, Rossa da Terza. Utilizzo: principalmente grappa, acquavite e uva da tavola. Non ammessi nella produzione DOC.',NULL,'Americana Rossa, Catawba, Isabella, Rossa da Terza. Usati per grappa, acquavite, uva da tavola. Non ammessi nella DOC.'),
('TICINO','classifica_colore','Classifica questi vitigni del Ticino come bianchi o rossi:',NULL,'{"Merlot":"Rosso","Bondola":"Rosso","Chardonnay":"Bianco","Sauvignon Blanc":"Bianco","Pinot Nero":"Rosso","Cabernet Franc":"Rosso","Isabella":"Rosso","Pinot Grigio":"Bianco"}',NULL,'["Merlot","Bondola","Chardonnay","Sauvignon Blanc","Pinot Nero","Cabernet Franc","Isabella","Pinot Grigio"]','La Bondola è l''unico autoctono rosso del Ticino. Isabella è un vitigno americano a bacca rossa. Pinot Grigio è bianco.'),
('TICINO','classifica_colore','Classifica questi termini del Ticino come vitigno bianco, vitigno rosso, specialità o altro:',NULL,'{"Merlot Bianco":"Specialità (blanc de noirs)","Bondola":"Rosso (autoctono)","Merlot Viti":"Specialità (etichetta qualità)","Monte Ceneri":"Altro (geografia)","Sopraceneri":"Altro (zona geografica)","Ticino DOC":"Specialità (AOC)"}',NULL,'["Merlot Bianco","Bondola","Merlot Viti","Monte Ceneri","Sopraceneri","Ticino DOC"]','Distinguere vitigni, specialità, denominazioni e geografie del Ticino è fondamentale.'),
('TICINO','abbinamento','Abbina ogni zona del Ticino alle sue caratteristiche pedologiche:',NULL,'{"Sopraceneri (Bellinzona, Locarno)":"Suoli glaciali-fluviali: granito, gneiss, rocce cristalline","Sottoceneri (Lugano, Mendrisiotto)":"Suoli morenichi: argilla, sabbia, ghiaia e calcari"}',NULL,'{"sx":["Sopraceneri (Bellinzona, Locarno)","Sottoceneri (Lugano, Mendrisiotto)"],"dx":["Suoli glaciali-fluviali: granito, gneiss, rocce cristalline","Suoli morenichi: argilla, sabbia, ghiaia e calcari"]}','Il Monte Ceneri separa due zone pedologicamente molto diverse.'),
('TICINO','abbinamento','Abbina ogni menzione speciale ticinese alla sua descrizione:',NULL,'{"Ticino DOC":"Unica AOC regionale del cantone","Merlot Bianco":"Blanc de noirs da Merlot, specialità emblematica","Bondola":"Unico vitigno autoctono rosso, quasi scomparso","Merlot Viti":"Etichetta qualità per Merlot rossi di 18 produttori","Riserva":"Millesimo obbligatorio e min 18 mesi invecchiamento"}',NULL,'{"sx":["Ticino DOC","Merlot Bianco","Bondola","Merlot Viti","Riserva"],"dx":["Unica AOC regionale del cantone","Blanc de noirs da Merlot, specialità emblematica","Unico vitigno autoctono rosso, quasi scomparso","Etichetta qualità per Merlot rossi di 18 produttori","Millesimo obbligatorio e min 18 mesi invecchiamento"]}','Il Ticino ha un sistema di denominazioni semplice (1 AOC) ma con menzioni speciali importanti.'),
('TICINO','comuni','Quale zona del Ticino è riconosciuta come la migliore per il Merlot di alta qualità?','{"a":"Locarno (Sopraceneri)","b":"Mendrisiotto (Sottoceneri)","c":"Bellinzona (Sopraceneri)","d":"Ascona (Sopraceneri)"}','"b"',NULL,NULL,'Il Mendrisiotto, nella parte più meridionale del Sottoceneri, è la zona d''eccellenza per il Merlot ticinese. Suoli morenichi con argilla e calcare.'),
('TICINO','comuni','In quale città ticinese si trova il capoluogo del cantone?','{"a":"Locarno","b":"Lugano","c":"Bellinzona","d":"Mendrisio"}','"c"',NULL,NULL,'Bellinzona è il capoluogo del cantone Ticino, nel Sopraceneri. Importante centro viticolo con i suoi castelli UNESCO.'),
('TICINO','comuni','A quale zona appartiene il comune di Morcote, noto per i suoi vigneti sul lago di Lugano?','{"a":"Sopraceneri","b":"Sottoceneri","c":"Alto Ticino","d":"Valle Maggia"}','"b"',NULL,NULL,'Morcote si trova nel Sottoceneri, sul lago di Lugano, uno dei borghi più belli della Svizzera. I suoi vigneti terrazzati producono Merlot di carattere.'),
('SVIZZERA_TEDESCA','multipla','La Svizzera Tedesca comprende quanti cantoni viticoli?','{"a":"5","b":"10","c":"17","d":"26"}','"c"',NULL,NULL,'La Svizzera Tedesca comprende 17 cantoni viticoli, con altrettante AOC cantonali (AOC Zürich, AOC Graubünden, AOC Schaffhausen, AOC Aargau...)'),
('SVIZZERA_TEDESCA','multipla','Come si chiama localmente il Pinot Noir nella Svizzera Tedesca?','{"a":"Spätburgunder","b":"Blauburgunder","c":"Klevner (a Zurigo)","d":"Sia Blauburgunder che Klevner a Zurigo"}','"d"',NULL,NULL,'Il Pinot Noir è chiamato Blauburgunder in tutta la Svizzera Tedesca, con l''eccezione di Zurigo dove è tradizionalmente noto come Klevner.'),
('SVIZZERA_TEDESCA','multipla','Cos''è il Räuschling?','{"a":"Il nome locale del Riesling nei Grigioni","b":"Un vitigno bianco storico autoctono di Zurigo","c":"Un incrocio svizzero rosso resistente alle malattie","d":"Il vento caldo tipico del cantone Turgovia"}','"b"',NULL,NULL,'Il Räuschling è un vitigno bianco autoctono e storico di Zurigo. Quasi scomparso nel XX secolo, è ora in fase di recupero.'),
('SVIZZERA_TEDESCA','multipla','Il Completer è un vitigno bianco autoctono di quale cantone?','{"a":"Zurigo","b":"Sciaffusa","c":"Grigioni (Graubünden)","d":"Turgovia"}','"c"',NULL,NULL,'Il Completer è il raro vitigno bianco autoctono dei Grigioni, con origini medievali. Produce vini di grande longevità, quasi impossibili da trovare fuori dalla Svizzera.'),
('SVIZZERA_TEDESCA','multipla','La Bündner Herrschaft nei Grigioni è nota come la Borgogna della Svizzera. Di quanti comuni è composta?','{"a":"2","b":"4","c":"6","d":"8"}','"b"',NULL,NULL,'La Bündner Herrschaft è composta da 4 comuni: Maienfeld, Jenins, Malans e Fläsch. Zona vinicola principale dei Grigioni, famosa per Pinot Nero su suoli argillosi profondi.'),
('SVIZZERA_TEDESCA','multipla','Come viene soprannominato il vento Föhn nella Svizzera Tedesca per il suo effetto sulle uve?','{"a":"Windzüchter","b":"Traubenkocher (cuocitore d''uva)","c":"Reifenmacher","d":"Sonnenbringer"}','"b"',NULL,NULL,'Il Föhn viene chiamato Traubenkocher (cuocitore d''uva) nella Svizzera Tedesca per il suo effetto fondamentale sulla maturazione delle uve in un clima altrimenti fresco.'),
('SVIZZERA_TEDESCA','multipla','Chi ha creato il Müller-Thurgau e quando?','{"a":"Un professore tedesco di Würzburg nel 1920","b":"Hermann Müller del cantone di Turgovia nel 1882","c":"Un istituto austriaco di Klosterneuburg nel 1900","d":"Georg Scheu nella Rheinhessen nel 1916"}','"b"',NULL,NULL,'Hermann Müller, originario del cantone di Turgovia (Thurgau), ha creato il Müller-Thurgau nel 1882. In Svizzera è chiamato Riesling-Sylvaner ma è in realtà Riesling x Madeleine Royale.'),
('SVIZZERA_TEDESCA','multipla','Quali sono gli incroci svizzeri rossi moderni resistenti alle malattie più presenti nella Svizzera Tedesca?','{"a":"Gamaret e Garanoir","b":"Regent e Cabernet Jura","c":"Doral e Charmont","d":"Räuschling e Completer"}','"b"',NULL,NULL,'Regent e Cabernet Jura sono gli incroci rossi moderni più presenti nella Svizzera Tedesca, specialmente a Zurigo. Resistenti alle malattie fungine.'),
('SVIZZERA_TEDESCA','multipla','Quale specialità è tipica dei Grigioni nella Svizzera Tedesca?','{"a":"Oeil de Perdrix","b":"Federweiss e Blanc de Noir da Pinot Noir","c":"Non Filtré","d":"Vin des Glaciers"}','"b"',NULL,NULL,'I Grigioni producono il Federweiss (Federweisser, vino giovane da fermentazione iniziale) e il Blanc de Noir da Pinot Nero. Specialità locali poco note fuori dal cantone.'),
('SVIZZERA_TEDESCA','multipla','Quale cantone della Svizzera Tedesca ha un''altitudine vitata che va dai 320 m fino ai 600 m?','{"a":"Turgovia","b":"Basilea","c":"Grigioni","d":"Argovia"}','"c"',NULL,NULL,'I Grigioni hanno l''altitudine più variabile della Svizzera Tedesca: da 320 m nelle valli fino a 600 m e oltre. La Bündner Herrschaft si trova nelle zone più basse.'),
('SVIZZERA_TEDESCA','vero_falso','Il Müller-Thurgau è un incrocio tra Riesling e Sylvaner, come indicato dal nome tradizionale svizzero Riesling-Sylvaner.',NULL,'false',NULL,NULL,'Falso. Nonostante il nome tradizionale svizzero Riesling-Sylvaner, gli studi genetici hanno dimostrato che il Müller-Thurgau è un incrocio tra Riesling e Madeleine Royale.'),
('SVIZZERA_TEDESCA','vero_falso','Il Räuschling è il vitigno bianco più piantato nel cantone di Zurigo.',NULL,'false',NULL,NULL,'Falso. Il Räuschling è quasi scomparso nel XX secolo ed è presente in piccole quantità. Il vitigno più piantato nella Svizzera Tedesca è il Pinot Noir (Blauburgunder).'),
('SVIZZERA_TEDESCA','vero_falso','La Bündner Herrschaft nei Grigioni è composta dai comuni di Maienfeld, Jenins, Malans e Fläsch.',NULL,'true',NULL,NULL,'Vero. La Bündner Herrschaft è composta esattamente da questi 4 comuni nel nord dei Grigioni, al confine con il Liechtenstein e San Gallo.'),
('SVIZZERA_TEDESCA','vero_falso','Il clima della Svizzera Tedesca è in generale più fresco, umido e meno soleggiato rispetto all''Ovest della Svizzera.',NULL,'true',NULL,NULL,'Vero. La Svizzera Tedesca ha un clima più fresco e umido (800-1.500 mm di pioggia) con alto rischio di gelate. Il Föhn e i laghi temperano il clima in alcune zone.'),
('SVIZZERA_TEDESCA','vero_falso','Il Completer dei Grigioni è quasi impossibile da trovare fuori dalla Svizzera.',NULL,'true',NULL,NULL,'Vero. Il Completer è un vitigno rarissimo coltivato quasi esclusivamente nei Grigioni. La produzione è pochissima e la distribuzione quasi esclusivamente locale.'),
('SVIZZERA_TEDESCA','vero_falso','Le 17 AOC della Svizzera Tedesca sono organizzate per singolo cantone.',NULL,'true',NULL,NULL,'Vero. Ogni cantone viticolo della Svizzera Tedesca ha la propria AOC cantonale (AOC Zürich, AOC Graubünden, AOC Schaffhausen, AOC Aargau, AOC Thurgau, ecc.).'),
('SVIZZERA_TEDESCA','aperta','Descrivi le caratteristiche del Müller-Thurgau e spiega perché il suo nome svizzero è fuorviante.',NULL,NULL,'Il Müller-Thurgau è stato creato nel 1882 da Hermann Müller, originario del cantone di Turgovia (Thurgau). In Svizzera è ancora chiamato Riesling-Sylvaner, nome che suggerisce un incrocio tra Riesling e Sylvaner. Gli studi genetici moderni hanno però dimostrato che è in realtà un incrocio tra Riesling e Madeleine Royale. È il vitigno bianco più importante della Svizzera Tedesca: matura precocemente, produce vini floreali e aromatici con buona acidità.',NULL,'Creato 1882, Hermann Müller (Thurgau). In Svizzera: Riesling-Sylvaner (fuorviante: è Riesling x Madeleine Royale). Matura presto, vini floreali e aromatici.'),
('SVIZZERA_TEDESCA','aperta','Descrivi la Bündner Herrschaft nei Grigioni: dove si trova, quali vitigni produce e perché è importante.',NULL,NULL,'La Bündner Herrschaft è la principale zona vinicola dei Grigioni, composta da 4 comuni: Maienfeld, Jenins, Malans e Fläsch. Si trova nel nord dei Grigioni, al confine con il Liechtenstein. È chiamata la Borgogna della Svizzera per la qualità del Pinot Nero su suoli profondi ricchi di argilla e minerali. Il Föhn è fondamentale per raggiungere la maturazione. Produce anche il raro Completer bianco autoctono.',NULL,'4 comuni: Maienfeld, Jenins, Malans, Fläsch. Nord Grigioni, confine Liechtenstein. Borgogna della Svizzera. Pinot Nero su suoli argillosi profondi. Föhn fondamentale.'),
('SVIZZERA_TEDESCA','aperta','Descrivi i vitigni autoctoni della Svizzera Tedesca: Räuschling e Completer.',NULL,NULL,'Räuschling: vitigno bianco storico e locale di Zurigo. Quasi scomparso nel XX secolo a causa della concorrenza di vitigni più produttivi. Ora in fase di recupero da parte di alcuni produttori zurighesi. Produce vini freschi e leggeri con acidità marcata. Completer: vitigno bianco autoctono dei Grigioni con origini medievali, citato già nel XIII secolo. Rarissimo, pochi ettari totali. Produce vini di grande longevità e complessità, quasi impossibili da trovare fuori dalla Svizzera.',NULL,'Räuschling: autoctono bianco di Zurigo, quasi scomparso, recupero in corso. Completer: autoctono bianco medievale dei Grigioni, rarissimo, grande longevità.'),
('SVIZZERA_TEDESCA','aperta','Descrivi il ruolo del Föhn nella Svizzera Tedesca e perché è chiamato Traubenkocher.',NULL,NULL,'Il Föhn è un vento caldo e secco che scende dalle Alpi, tipico di molte zone della Svizzera Tedesca (soprattutto Grigioni, Uri, Svitto). Nella Svizzera Tedesca è chiamato Traubenkocher (cuocitore d''uva) perché accelera drammaticamente la maturazione delle uve nelle zone che altrimenti avrebbero difficoltà per il clima fresco e umido. Il Föhn può alzare le temperature di 10-15 gradi in poche ore, essenziale per la maturazione del Pinot Nero nelle zone settentrionali.',NULL,'Föhn: vento caldo-secco alpino. Traubenkocher: cuocitore d''uva. Accelera la maturazione di 10-15°C in poche ore. Fondamentale per Pinot Nero nelle zone fredde.'),
('SVIZZERA_TEDESCA','elenco','Elenca i vitigni autoctoni della Svizzera Tedesca (bianchi e rossi).',NULL,NULL,'Bianchi autoctoni: Räuschling (Zurigo), Completer (Grigioni). Nessun autoctono rosso vero: il Pinot Nero (Blauburgunder) è il principale ma non è autoctono svizzero. Incroci svizzeri recenti: Regent, Cabernet Jura, Gamaret (rossi).',NULL,'Bianchi autoctoni: Räuschling (Zurigo), Completer (Grigioni). Nessun autoctono rosso. Incroci recenti: Regent, Cabernet Jura (rossi).'),
('SVIZZERA_TEDESCA','elenco','Elenca almeno 5 cantoni viticoli della Svizzera Tedesca.',NULL,NULL,'Zurigo, Grigioni (Graubünden), Sciaffusa (Schaffhausen), Argovia (Aargau), Turgovia (Thurgau), Basilea Campagna (Basel-Landschaft), San Gallo (St. Gallen). Totale 17 cantoni viticoli.',NULL,'Zurigo, Grigioni, Sciaffusa, Argovia, Turgovia, Basilea Campagna, San Gallo (totale 17 cantoni).'),
('SVIZZERA_TEDESCA','elenco','Elenca le specialità enologiche tipiche dei Grigioni nella Svizzera Tedesca.',NULL,NULL,'1. Completer: vitigno bianco autoctono medievale, rarissimo. 2. Federweiss/Federweisser: vino giovane da fermentazione iniziale. 3. Blanc de Noir: Pinot Nero vinificato in bianco. 4. Pinot Nero della Bündner Herrschaft: la Borgogna svizzera.',NULL,'Completer (bianco autoctono), Federweiss (vino giovane), Blanc de Noir (PN in bianco), Pinot Nero della Bündner Herrschaft.'),
('SVIZZERA_TEDESCA','classifica_colore','Classifica questi vitigni tipici della Svizzera Tedesca come bianchi o rossi:',NULL,'{"Pinot Noir (Blauburgunder)":"Rosso","Räuschling":"Bianco","Completer":"Bianco","Müller-Thurgau":"Bianco","Regent":"Rosso","Cabernet Jura":"Rosso","Gamaret":"Rosso","Pinot Gris (Grauburgunder)":"Bianco"}',NULL,'["Pinot Noir (Blauburgunder)","Räuschling","Completer","Müller-Thurgau","Regent","Cabernet Jura","Gamaret","Pinot Gris (Grauburgunder)"]','Räuschling e Completer sono gli unici autoctoni bianchi. Regent e Cabernet Jura sono incroci moderni rossi resistenti alle malattie.'),
('SVIZZERA_TEDESCA','classifica_colore','Classifica questi termini della Svizzera Tedesca come vitigno bianco, vitigno rosso, vento o denominazione:',NULL,'{"Blauburgunder":"Rosso","Traubenkocher":"Vento (Föhn)","Räuschling":"Bianco","Bündner Herrschaft":"Denominazione/Zona","Completer":"Bianco","Federweiss":"Specialità (vino giovane)"}',NULL,'["Blauburgunder","Traubenkocher","Räuschling","Bündner Herrschaft","Completer","Federweiss"]','Traubenkocher è il soprannome del Föhn, non un vitigno. Bündner Herrschaft è una zona geografica/denominazione.'),
('SVIZZERA_TEDESCA','abbinamento','Abbina ogni cantone della Svizzera Tedesca al suo vitigno/caratteristica principale:',NULL,'{"Zurigo":"Räuschling (autoctono bianco storico) e Blauburgunder","Grigioni (Bündner Herrschaft)":"Completer (autoctono medievale) e Pinot Nero di qualità borgognona","Sciaffusa":"Pinot Nero su suoli calcarei, confine tedesco","Turgovia e Argovia":"Müller-Thurgau, zona di creazione del vitigno"}',NULL,'{"sx":["Zurigo","Grigioni (Bündner Herrschaft)","Sciaffusa","Turgovia e Argovia"],"dx":["Räuschling (autoctono bianco storico) e Blauburgunder","Completer (autoctono medievale) e Pinot Nero di qualità borgognona","Pinot Nero su suoli calcarei, confine tedesco","Müller-Thurgau, zona di creazione del vitigno"]}','Ogni cantone della Svizzera Tedesca ha la propria identità viticola.'),
('SVIZZERA_TEDESCA','abbinamento','Abbina ogni termine della Svizzera Tedesca alla sua definizione:',NULL,'{"Räuschling":"Vitigno bianco autoctono e storico di Zurigo, quasi scomparso","Completer":"Vitigno bianco autoctono medievale dei Grigioni, rarissimo","Traubenkocher":"Soprannome del Föhn per il suo effetto sulla maturazione delle uve","Blauburgunder":"Nome locale del Pinot Nero in tutta la Svizzera Tedesca","Bündner Herrschaft":"La Borgogna della Svizzera, 4 comuni nel nord dei Grigioni"}',NULL,'{"sx":["Räuschling","Completer","Traubenkocher","Blauburgunder","Bündner Herrschaft"],"dx":["Vitigno bianco autoctono e storico di Zurigo, quasi scomparso","Vitigno bianco autoctono medievale dei Grigioni, rarissimo","Soprannome del Föhn per il suo effetto sulla maturazione delle uve","Nome locale del Pinot Nero in tutta la Svizzera Tedesca","La Borgogna della Svizzera, 4 comuni nel nord dei Grigioni"]}','Conoscere i termini locali della Svizzera Tedesca è fondamentale per l''esame ASPI.'),
('SVIZZERA_TEDESCA','comuni','In quale area dei Grigioni si trova la Bündner Herrschaft?','{"a":"Coira (Chur), centro dei Grigioni","b":"Maienfeld, Jenins, Malans, Fläsch nel nord dei Grigioni","c":"Davos e St. Moritz","d":"Bellinzona, al confine con il Ticino"}','"b"',NULL,NULL,'La Bündner Herrschaft si trova nei 4 comuni di Maienfeld, Jenins, Malans e Fläsch, nel nord dei Grigioni, al confine con il Liechtenstein e San Gallo.'),
('SVIZZERA_TEDESCA','comuni','In quale città è situata la scuola di viticoltura ZHAW, importante istituto di ricerca viticola della Svizzera?','{"a":"Zurigo","b":"Berna","c":"Wädenswil (Zurigo)","d":"Winterthur"}','"c"',NULL,NULL,'Wädenswil, sul lago di Zurigo, ospita la ZHAW (Zürcher Hochschule für Angewandte Wissenschaften), con un importante istituto di ricerca e formazione viticola.'),
('SVIZZERA_TEDESCA','comuni','Quale città è associata al Räuschling, il vitigno bianco storico di Zurigo?','{"a":"Winterthur","b":"Zürich (Zurigo)","c":"Schaffhausen","d":"Baden"}','"b"',NULL,NULL,'Il Räuschling è storicamente legato ai vigneti attorno alla città di Zurigo e al lago di Zurigo (Zürichsee). Era diffuso in tutta la regione prima che Müller-Thurgau e Pinot Nero diventassero dominanti.');
